// T(n) = T(n/2) + O(1)  ->  O(log n) time, O(log n) stack
int Search(int[] a, int target, int lo, int hi)
{
    if (lo > hi) return -1;
    int mid = lo + (hi - lo) / 2;
    if (a[mid] == target) return mid;
    return a[mid] < target ? Search(a, target, mid + 1, hi)
                           : Search(a, target, lo, mid - 1);
}

