int SubarraySum(int[] a, int k)
{
    var seen = new Dictionary<long, int> { [0] = 1 };
    long running = 0;
    int count = 0;
    foreach (int x in a)
    {
        running += x;
        if (seen.TryGetValue(running - k, out int c)) count += c;
        seen[running] = seen.TryGetValue(running, out int cur) ? cur + 1 : 1;
    }
    return count;
}

int LengthOfLongestSubstring(string s)
{
    var last = new Dictionary<char, int>();
    int best = 0, left = 0;
    for (int right = 0; right < s.Length; right++)
    {
        char c = s[right];
        if (last.TryGetValue(c, out int prev))
            left = Math.Max(left, prev + 1);   // never move left backwards
        last[c] = right;
        best = Math.Max(best, right - left + 1);
    }
    return best;
}
