void MergeSort(int[] a)
{
    var tmp = new int[a.Length];          // one shared buffer: O(n) extra space
    Sort(a, tmp, 0, a.Length - 1);
}

void Sort(int[] a, int[] tmp, int lo, int hi)
{
    if (lo >= hi) return;
    int mid = lo + (hi - lo) / 2;
    Sort(a, tmp, lo, mid);
    Sort(a, tmp, mid + 1, hi);

    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi)
        tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];   // <= keeps equal items in order (stable)
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi)  tmp[k++] = a[j++];
    Array.Copy(tmp, lo, a, lo, hi - lo + 1);
}

int Partition(int[] a, int lo, int hi)     // Lomuto partition, pivot = a[hi]
{
    int pivot = a[hi], i = lo;
    for (int j = lo; j < hi; j++)
        if (a[j] < pivot) { (a[i], a[j]) = (a[j], a[i]); i++; }
    (a[i], a[hi]) = (a[hi], a[i]);
    return i;                               // pivot's final position
}

