int[][] Merge(int[][] intervals)
{
    if (intervals.Length == 0) return intervals;

    var sorted = intervals.Select(iv => new[] { iv[0], iv[1] }).ToArray();   // don't mutate the input
    Array.Sort(sorted, (a, b) => a[0].CompareTo(b[0]));                      // O(n log n)

    var result = new List<int[]> { sorted[0] };
    for (int i = 1; i < sorted.Length; i++)
    {
        int[] last = result[^1];
        int[] cur = sorted[i];
        if (cur[0] <= last[1])                  // overlaps (touching counts here)
            last[1] = Math.Max(last[1], cur[1]);
        else
            result.Add(cur);
    }
    return result.ToArray();
}
