int BinarySearch(int[] a, int target)
{
    int lo = 0, hi = a.Length - 1;              // inclusive bounds
    while (lo <= hi)
    {
        int mid = lo + (hi - lo) / 2;           // no overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;      // always shrink the range
        else hi = mid - 1;
    }
    return -1;
}

// First index with a[i] >= target (a.Length if none): half-open [lo, hi)
int LowerBound(int[] a, int target)
{
    int lo = 0, hi = a.Length;
    while (lo < hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

