int ShipWithinDays(int[] weights, int days)
{
    int lo = weights.Max();                  // must fit the heaviest package
    int hi = weights.Sum();                  // everything in one day
    while (lo < hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (DaysNeeded(weights, mid) <= days) hi = mid;   // feasible: try smaller
        else lo = mid + 1;
    }
    return lo;                               // smallest feasible capacity
}

int DaysNeeded(int[] weights, int capacity)
{
    int days = 1, load = 0;
    foreach (int w in weights)
    {
        if (load + w > capacity) { days++; load = 0; }
        load += w;
    }
    return days;
}

