bool TryFloor(SortedSet<int> s, int x, out int floor)
{
    floor = default;
    if (s.Count == 0 || x < s.Min) return false;
    floor = s.GetViewBetween(s.Min, x).Max;      // view is non-empty: it contains s.Min
    return true;
}

bool TryCeiling(SortedSet<int> s, int x, out int ceiling)
{
    ceiling = default;
    if (s.Count == 0 || x > s.Max) return false;
    ceiling = s.GetViewBetween(x, s.Max).Min;
    return true;
}

bool IsValid(string s)
{
    var expected = new Stack<char>();
    foreach (char c in s)
    {
        switch (c)
        {
            case '(': expected.Push(')'); break;
            case '[': expected.Push(']'); break;
            case '{': expected.Push('}'); break;
            default:
                if (!expected.TryPop(out char want) || want != c) return false;
                break;
        }
    }
    return expected.Count == 0;          // leftover openers are invalid
}
