public sealed class TwoStackQueue<T>
{
    private readonly Stack<T> _in = new();
    private readonly Stack<T> _out = new();

    public int Count => _in.Count + _out.Count;

    public void Enqueue(T item) => _in.Push(item);

    public T Dequeue()
    {
        Shift();
        return _out.Pop();                    // throws InvalidOperationException if empty
    }

    public T Peek()
    {
        Shift();
        return _out.Peek();
    }

    private void Shift()
    {
        if (_out.Count > 0) return;           // only refill when out is empty
        while (_in.Count > 0) _out.Push(_in.Pop());
    }
}

int[] NextGreater(int[] a)
{
    var result = new int[a.Length];
    Array.Fill(result, -1);
    var waiting = new Stack<int>();          // indices; their values decrease towards the top

    for (int i = 0; i < a.Length; i++)
    {
        while (waiting.Count > 0 && a[waiting.Peek()] < a[i])
            result[waiting.Pop()] = a[i];    // a[i] is the first greater value to the right
        waiting.Push(i);
    }
    return result;                           // indices still waiting keep -1
}
