int FindKthLargest(int[] nums, int k)
{
    var heap = new PriorityQueue<int, int>(k);    // min-heap of the k largest so far
    foreach (int x in nums)
    {
        if (heap.Count < k)
            heap.Enqueue(x, x);
        else if (x > heap.Peek())
            heap.EnqueueDequeue(x, x);            // add x, drop the current smallest
    }
    return heap.Peek();
}
