List<int> MergeK(IReadOnlyList<int[]> lists)
{
    var heap = new PriorityQueue<(int List, int Index), int>();
    for (int i = 0; i < lists.Count; i++)
        if (lists[i].Length > 0)
            heap.Enqueue((i, 0), lists[i][0]);

    var result = new List<int>();
    while (heap.TryDequeue(out var pos, out int value))
    {
        result.Add(value);
        int next = pos.Index + 1;
        if (next < lists[pos.List].Length)
            heap.Enqueue((pos.List, next), lists[pos.List][next]);
    }
    return result;
}
