int[] BfsDistances(List<int>[] adj, int start)      // edges from start, -1 = unreachable
{
    var dist = new int[adj.Length];
    Array.Fill(dist, -1);
    dist[start] = 0;
    var queue = new Queue<int>();
    queue.Enqueue(start);

    while (queue.Count > 0)
    {
        int u = queue.Dequeue();
        foreach (int v in adj[u])
            if (dist[v] == -1)                       // doubles as the visited check
            {
                dist[v] = dist[u] + 1;
                queue.Enqueue(v);
            }
    }
    return dist;
}

void Dfs(List<int>[] adj, int u, bool[] visited, List<int> order)
{
    visited[u] = true;
    order.Add(u);
    foreach (int v in adj[u])
        if (!visited[v]) Dfs(adj, v, visited, order);
}

void InOrder(TreeNode? node, List<int> output)
{
    if (node is null) return;
    InOrder(node.Left, output);
    output.Add(node.Val);          // pre-order: before both calls; post-order: after both
    InOrder(node.Right, output);
}

List<int> InOrderIterative(TreeNode? root)
{
    var output = new List<int>();
    var stack = new Stack<TreeNode>();
    TreeNode? current = root;
    while (current is not null || stack.Count > 0)
    {
        while (current is not null) { stack.Push(current); current = current.Left; }
        current = stack.Pop();
        output.Add(current.Val);
        current = current.Right;
    }
    return output;
}

List<List<int>> LevelOrder(TreeNode? root)
{
    var levels = new List<List<int>>();
    if (root is null) return levels;
    var queue = new Queue<TreeNode>();
    queue.Enqueue(root);
    while (queue.Count > 0)
    {
        int size = queue.Count;                 // nodes on this level
        var level = new List<int>(size);
        for (int i = 0; i < size; i++)
        {
            TreeNode node = queue.Dequeue();
            level.Add(node.Val);
            if (node.Left is not null) queue.Enqueue(node.Left);
            if (node.Right is not null) queue.Enqueue(node.Right);
        }
        levels.Add(level);
    }
    return levels;
}

