int NumIslands(char[][] grid)
{
    int rows = grid.Length, cols = grid[0].Length, islands = 0;
    var dirs = new (int Dr, int Dc)[] { (1, 0), (-1, 0), (0, 1), (0, -1) };
    var queue = new Queue<(int R, int C)>();

    for (int r = 0; r < rows; r++)
    for (int c = 0; c < cols; c++)
    {
        if (grid[r][c] != '1') continue;
        islands++;
        grid[r][c] = '0';                       // mark when enqueuing
        queue.Enqueue((r, c));

        while (queue.Count > 0)
        {
            var (cr, cc) = queue.Dequeue();
            foreach (var (dr, dc) in dirs)
            {
                int nr = cr + dr, nc = cc + dc;
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '1')
                {
                    grid[nr][nc] = '0';
                    queue.Enqueue((nr, nc));
                }
            }
        }
    }
    return islands;
}

bool IsValidBst(TreeNode? node, long min = long.MinValue, long max = long.MaxValue)
{
    if (node is null) return true;
    if (node.Val <= min || node.Val >= max) return false;      // strict: no duplicates
    return IsValidBst(node.Left, min, node.Val)
        && IsValidBst(node.Right, node.Val, max);
}

