List<int>? TopologicalOrder(int n, int[][] edges)      // edge [u, v]: u must come before v
{
    var adj = new List<int>[n];
    for (int i = 0; i < n; i++) adj[i] = new List<int>();
    var indegree = new int[n];
    foreach (var e in edges) { adj[e[0]].Add(e[1]); indegree[e[1]]++; }

    var ready = new Queue<int>();
    for (int i = 0; i < n; i++)
        if (indegree[i] == 0) ready.Enqueue(i);

    var order = new List<int>(n);
    while (ready.Count > 0)
    {
        int u = ready.Dequeue();
        order.Add(u);
        foreach (int v in adj[u])
            if (--indegree[v] == 0) ready.Enqueue(v);
    }
    return order.Count == n ? order : null;            // null: there's a cycle
}

long[] Dijkstra(List<(int To, int Weight)>[] adj, int source)
{
    var dist = new long[adj.Length];
    Array.Fill(dist, long.MaxValue);
    dist[source] = 0;

    var pq = new PriorityQueue<int, long>();
    pq.Enqueue(source, 0);

    while (pq.TryDequeue(out int u, out long d))
    {
        if (d > dist[u]) continue;                 // stale entry: already improved
        foreach (var (v, w) in adj[u])
        {
            long nd = d + w;
            if (nd < dist[v])
            {
                dist[v] = nd;
                pq.Enqueue(v, nd);                 // no decrease-key: push a new entry
            }
        }
    }
    return dist;                                   // long.MaxValue = unreachable
}

public sealed class DisjointSet
{
    private readonly int[] _parent;
    private readonly int[] _size;
    public int Components { get; private set; }

    public DisjointSet(int n)
    {
        _parent = new int[n];
        _size = new int[n];
        for (int i = 0; i < n; i++) { _parent[i] = i; _size[i] = 1; }
        Components = n;
    }

    public int Find(int x)
    {
        while (_parent[x] != x)
        {
            _parent[x] = _parent[_parent[x]];      // path halving
            x = _parent[x];
        }
        return x;
    }

    public bool Union(int a, int b)
    {
        int ra = Find(a), rb = Find(b);
        if (ra == rb) return false;                // already connected: this edge would close a cycle
        if (_size[ra] < _size[rb]) (ra, rb) = (rb, ra);
        _parent[rb] = ra;                          // smaller tree under the larger one
        _size[ra] += _size[rb];
        Components--;
        return true;
    }
}

// Depth n: fine for small n, but a very deep input can crash the process
long SumTo(int n) => n == 0 ? 0 : n + SumTo(n - 1);

// Same result with O(1) stack
long SumToIterative(int n)
{
    long total = 0;
    for (int i = 1; i <= n; i++) total += i;
    return total;
}

// Recursive DFS rewritten with an explicit stack
List<int> DfsIterative(List<int>[] adj, int start)
{
    var order = new List<int>();
    var visited = new bool[adj.Length];
    var stack = new Stack<int>();
    stack.Push(start);
    while (stack.Count > 0)
    {
        int u = stack.Pop();
        if (visited[u]) continue;
        visited[u] = true;
        order.Add(u);
        for (int i = adj[u].Count - 1; i >= 0; i--)    // reversed so neighbours are visited in list order
            if (!visited[adj[u][i]]) stack.Push(adj[u][i]);
    }
    return order;
}

// Naive: O(2^n)-style blow-up from recomputation
long FibNaive(int n) => n < 2 ? n : FibNaive(n - 1) + FibNaive(n - 2);

// Top-down: O(n) time, O(n) cache + O(n) stack
long FibMemo(int n, long[]? memo = null)
{
    if (n < 2) return n;
    memo ??= new long[n + 1];
    if (memo[n] != 0) return memo[n];
    return memo[n] = FibMemo(n - 1, memo) + FibMemo(n - 2, memo);
}

// Bottom-up: O(n) time, O(1) space
long FibTab(int n)
{
    if (n < 2) return n;
    long prev = 0, cur = 1;
    for (int i = 2; i <= n; i++)
        (prev, cur) = (cur, prev + cur);
    return cur;
}

int CoinChange(int[] coins, int amount)
{
    var dp = new int[amount + 1];             // dp[a] = fewest coins for amount a
    Array.Fill(dp, int.MaxValue);
    dp[0] = 0;

    for (int a = 1; a <= amount; a++)
        foreach (int c in coins)
            if (c <= a && dp[a - c] != int.MaxValue)
                dp[a] = Math.Min(dp[a], dp[a - c] + 1);

    return dp[amount] == int.MaxValue ? -1 : dp[amount];
}
// CoinChange(new[] {1, 3, 4}, 6) == 2   (3 + 3)

long CountWays(int[] coins, int amount)        // combinations, order doesn't matter
{
    var ways = new long[amount + 1];
    ways[0] = 1;
    foreach (int c in coins)                   // coins outer -> combinations
        for (int a = c; a <= amount; a++)
            ways[a] += ways[a - c];
    return ways[amount];
}

int LongestCommonSubsequence(string a, string b)
{
    if (a.Length < b.Length) (a, b) = (b, a);    // make b the shorter: rows of length |b| + 1
    var prev = new int[b.Length + 1];
    var cur = new int[b.Length + 1];

    for (int i = 1; i <= a.Length; i++)
    {
        for (int j = 1; j <= b.Length; j++)
            cur[j] = a[i - 1] == b[j - 1]
                ? prev[j - 1] + 1
                : Math.Max(prev[j], cur[j - 1]);
        (prev, cur) = (cur, prev);
    }
    return prev[b.Length];
}
// LongestCommonSubsequence("abcde", "ace") == 3

IList<IList<int>> Subsets(int[] nums)
{
    var result = new List<IList<int>>();
    var current = new List<int>();

    void Backtrack(int start)
    {
        result.Add(new List<int>(current));        // copy: current keeps changing
        for (int i = start; i < nums.Length; i++)
        {
            current.Add(nums[i]);                  // choose
            Backtrack(i + 1);                      // explore
            current.RemoveAt(current.Count - 1);   // un-choose
        }
    }

    Backtrack(0);
    return result;
}
// Subsets(new[] {1, 2, 3}) -> [], [1], [1,2], [1,2,3], [1,3], [2], [2,3], [3]

int Knapsack01(int[] weights, int[] values, int capacity)
{
    var best = new int[capacity + 1];               // best[w] = max value within weight w
    for (int i = 0; i < weights.Length; i++)
        for (int w = capacity; w >= weights[i]; w--) // downwards: item i used at most once
            best[w] = Math.Max(best[w], best[w - weights[i]] + values[i]);
    return best[capacity];
}

int KnapsackUnbounded(int[] weights, int[] values, int capacity)
{
    var best = new int[capacity + 1];
    for (int i = 0; i < weights.Length; i++)
        for (int w = weights[i]; w <= capacity; w++) // upwards: item i may be reused
            best[w] = Math.Max(best[w], best[w - weights[i]] + values[i]);
    return best[capacity];
}
// Knapsack01(new[] {1, 3, 4}, new[] {15, 20, 30}, 4) == 35  (items 0 and 1)
